package com.github.catvod.utils;import java.io.*;import java.nio.file.*;public class Path {public static File epg(){return new File(System.getProperty("epg.fixture.cache",System.getProperty("java.io.tmpdir")));}public static File epg(String s){return new File(epg(),s);}public static boolean exists(File f){return f.exists();}public static void clear(File f){if(f!=null)f.delete();}public static void move(File a,File b)throws IOException{Files.move(a.toPath(),b.toPath(),StandardCopyOption.REPLACE_EXISTING);}}
